{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Pentazocine, the closest analogue by Morgan similarity and sharing the N-prenyl tertiary amine motif, has a mean absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "MK-458, a lipophilic N-heterocycle with a basic amine, had an absolute oral bioavailability of only about 5% in patients, showing that such scaffolds can be severely limited by absorption or first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "8-Prenylnaringenin, a prenylated natural product, showed low oral bioavailability in humans, supporting the idea that prenyl substitution can impair oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Doravirine, an NNRTI, has about 64% absolute oral bioavailability, showing high F is possible in the antiviral class, but its optimized polar structure is not transferable to the lipophilic thione-containing query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Balovaptan has 100% oral bioavailability in adults, but its BCS class I-like properties are not shared by the lipophilic, poorly soluble query scaffold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted low: the closest analogue (pentazocine, F=18%) and several other transferable lipophilic/prenylated molecules (MK-458 ~5%, prenylflavonoids low) support F<20%; high-F analogues are structurally distant and lack the query's lipophilic thione/prenyl liabilities.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for the exact TIBO-like scaffold were retrieved.",
    "All retrieved analogues have Morgan similarity below 0.3, limiting structural transferability.",
    "Pentazocine lacks the thione and chloro-fused heterocycle present in the query.",
    "High-F NNRTI evidence comes from a structurally optimized molecule rather than a close analogue."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

